define(["jquery","local_video_bridge/html5"],function($,Html5Adapter){let apiPromise;const loadApi=url=>{if(window.Hls&&typeof window.Hls.isSupported==="function")return Promise.resolve(window.Hls);if(!apiPromise){apiPromise=new Promise((resolve,reject)=>{require([url],module=>{const Hls=module&&(module.default||module.Hls||module)||window.Hls;if(Hls&&typeof Hls.isSupported==="function"){resolve(Hls)}else{reject(new Error("HLS Player API did not load"))}},reject)})}return apiPromise};class HlsAdapter extends Html5Adapter{initialise(){if(this.video&&this.video.canPlayType("application/vnd.apple.mpegurl")){this.video.src=this.config.url;return super.initialise()}return loadApi(this.config.hlsjsurl).then(Hls=>{if(!Hls||!Hls.isSupported()){throw new Error("HLS is not supported by this browser")}this.hls=new Hls({enableWorker:true,lowLatencyMode:true});this.hls.loadSource(this.config.url);this.hls.attachMedia(this.video);return super.initialise()})}}return HlsAdapter});